#!/usr/bin/env python3
from __future__ import annotations
from typing import Any
def score(props:dict[str,Any],style:dict[str,Any],rights:list[dict[str,Any]],thresholds:dict[str,Any])->dict[str,Any]:
    weights=thresholds.get("weights") or {}; scenes=props.get("scenes") or []; captions=props.get("captions") or []; profile=props.get("captionProfile") or {}; resets=[(float(s.get("to",0))-float(s.get("from",0)))/30.0 for s in scenes if float(s.get("to",0))>float(s.get("from",0))]; max_reset=max(resets) if resets else 999.0; external=[x for x in rights if x.get("materialized")]; rights_ok=all(x.get("sourceUrl") and x.get("license") for x in external)
    metrics={"hook":1.0 if scenes else 0.0,"captionReadability":1.0 if int(profile.get("fontSize",0))>=64 and int(profile.get("maxLines",2))<=2 else 0.55,"visualReset":1.0 if max_reset<=float((thresholds.get("hardRules") or {}).get("visualResetMaxSeconds",3.0)) else max(0.25,3.0/max_reset),"assetDiversity":min(1.0,len({s.get("kind") for s in scenes})/3.0) if scenes else 0.0,"motion":1.0 if any(s.get("motion") not in {None,"none"} for s in scenes) else 0.5,"sound":1.0 if props.get("soundDesign") else 0.65,"branding":1.0 if props.get("proEditDesk",{}).get("enabled") else 0.5,"cta":1.0 if props.get("cta") else 0.4,"rights":1.0 if rights_ok else 0.0}; total=sum(float(weights.get(k,0)) for k in metrics) or 1.0; overall=sum(metrics[k]*float(weights.get(k,0)) for k in metrics)/total*100; minimum=float(thresholds.get("minimumScore",85)); return {"score":round(overall,1),"pass":overall>=minimum,"minimumScore":minimum,"metrics":{k:round(v*100,1) for k,v in metrics.items()},"maxVisualResetSeconds":round(max_reset,3) if resets else None,"captionCount":len(captions),"externalRightsCount":len(external)}
